        /// <summary>
        /// Get medicine component by product id
        /// </summary>
        /// <param name="productID"></param>
        /// <returns></returns>
        public List<MEMedicineComponentsInfo> GetMedicineComponentListByProductID(int productID)
        {
            DataSet ds = dal.GetDataSet("MEMedicineComponents_GetMedicineComponentListByProductID", productID);
            List<MEMedicineComponentsInfo> medicineComponentList = new List<MEMedicineComponentsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    MEMedicineComponentsInfo objMedicineComponentsInfo = (MEMedicineComponentsInfo)GetObjectFromDataRow(row);
                    medicineComponentList.Add(objMedicineComponentsInfo);
                }
            }
            return medicineComponentList;
        }
    }
